(function(){"use strict";function e(){const n=document.querySelector(".type-target");if(!n)return;const a=n.dataset.terms||"",s=a.split(",").filter(Boolean);if(!s.length)return;let o=0,e=0,i=!1;const r=100,c=50,l=2e3,d=300;function t(){const a=s[o];if(i){if(e--,n.textContent=a.slice(0,e),e<=0){i=!1,o=(o+1)%s.length,setTimeout(t,d);return}setTimeout(t,c)}else{if(e++,n.textContent=a.slice(0,e),e>=a.length){i=!0,setTimeout(t,l);return}setTimeout(t,r)}}t()}function t(){document.querySelectorAll(".copy-btn").forEach(e=>{e.addEventListener("click",()=>{const t=e.closest(".code-block")?.querySelector("code");if(!t)return;navigator.clipboard.writeText(t.textContent).then(()=>{const t=e.textContent;e.textContent="Copied!",e.classList.add("copied"),setTimeout(()=>{e.textContent=t,e.classList.remove("copied")},1500)})})})}function n(){const e=document.getElementById("terminfo-search"),t=document.getElementById("terminfo-list");if(!e||!t)return;const n=t.querySelectorAll(".terminfo-item");e.addEventListener("input",()=>{const t=e.value.toLowerCase().trim();n.forEach(e=>{const n=e.dataset.name||"",s=e.textContent.toLowerCase(),o=!t||n.includes(t)||s.includes(t);e.classList.toggle("hidden",!o)})})}document.addEventListener("DOMContentLoaded",()=>{e(),t(),n()})})()